import { AlignMethod, layoutChain } from "@kvisaz/phaser-sugar";
import { createGO, Observable, TypedEventsEmitter } from "../../../../common";
import { ViewElementBuilder } from "../../../../assets";
import { ISpiderGameViewEvents } from "../../logic";
import { ISpiderExposedState } from "../../../../common/games/spider";

interface IProps {
  scene: Phaser.Scene;
  gameState: Observable<ISpiderExposedState>;
  spiderSceneViewEvents: TypedEventsEmitter<ISpiderGameViewEvents>;
}

export class SpiderControls extends Phaser.GameObjects.Container {
  private readonly unSubs: Array<() => void> = [];

  constructor(private readonly props: IProps) {
    super(props.scene);
    const buttons = this.createButtons();

    layoutChain({
      children: buttons,
      alignToNext: AlignMethod.BOTTOM_TO,
      nextOffsetY: 16,
      alignToAnchor: AlignMethod.LEFT_IN,
    });

    this.add(buttons);
    this.scene.add.existing(this);
  }

  destroy() {
    super.destroy();
    this.unSubs.forEach((u) => u());
    this.unSubs.length = 0;
  }

  private createButtons() {
    const { scene, gameState, spiderSceneViewEvents } = this.props;
    const builder = new ViewElementBuilder(scene);

    const newGameButton = createGO(() => builder.buttonNewGame(() => spiderSceneViewEvents.emit("uiNewGameClick")));

    const undoButton = createGO(
      () =>
        builder.buttonSecondary("Undo", () => spiderSceneViewEvents.emit("uiUndoClick"), {
          width: 220,
          fontSizePx: 30,
        }),
      {
        use: (button) => {
          const applyState = (state: ISpiderExposedState) => button.enable(state.isUndoPossible);
          this.unSubs.push(gameState.on(applyState, ["isUndoPossible", "step"]));
          applyState(gameState.getState());
        },
      },
    );

    const hintButton = createGO(
      () =>
        builder.buttonSecondary("Hint", () => spiderSceneViewEvents.emit("uiHintClick"), {
          width: 220,
          fontSizePx: 30,
        }),
      {
        use: (button) => {
          const applyState = (state: ISpiderExposedState) => button.enable(state.step === "idle");
          this.unSubs.push(gameState.on(applyState, "step"));
          applyState(gameState.getState());
        },
      },
    );

    const dealButton = createGO(
      () =>
        builder.buttonSecondary("Deal", () => spiderSceneViewEvents.emit("uiDealClick"), {
          width: 220,
          fontSizePx: 30,
        }),
      {
        use: (button) => {
          const applyState = (state: ISpiderExposedState) => button.enable(state.isDealPossible);
          this.unSubs.push(gameState.on(applyState, ["isDealPossible", "step"]));
          applyState(gameState.getState());
        },
      },
    );

    return [newGameButton, undoButton, hintButton, dealButton];
  }
}

