import { GameLogicState } from "./types";
import {ConsumableType} from '../../../logic';

export const getDefaultConsumableStateRecord = (): Record<ConsumableType, boolean> => ({
  MAGIC: false,
  UNDO: false,
  VISION: false,
  HINT: false,
});

export function getDefaultState(): GameLogicState {
  return {
    consumableBalance: {
      UNDO: 0,
      HINT: 0,
      MAGIC: 0,
      VISION: 0,
    },
    consumableButtonsEnabled: getDefaultConsumableStateRecord(),
    score: 0,
  };
}
