import { Observable } from "../../../../common";
import { ISpiderExposedState } from "../../../../common/games/spider";

interface IProps {
  scene: Phaser.Scene;
  gameState: Observable<ISpiderExposedState>;
}

export class SpiderInfoUi extends Phaser.GameObjects.Container {
  private readonly unSubs: Array<() => void> = [];
  private readonly label: Phaser.GameObjects.Text;

  constructor(private readonly props: IProps) {
    super(props.scene);
    const { scene, gameState } = props;

    this.label = new Phaser.GameObjects.Text(scene, 0, 0, "", {
      fontFamily: "Arial",
      fontSize: "32px",
      color: "#ffffff",
    });
    this.add(this.label);
    scene.add.existing(this);

    const applyState = (state: ISpiderExposedState) => {
      const winText = state.isWin ? " WIN" : "";
      this.label.setText(
        `Deals: ${state.dealsLeft}  Completed: ${state.completedSequences}/8  Undo: ${state.historyLength}${winText}`,
      );
    };

    this.unSubs.push(gameState.on(applyState));
    applyState(gameState.getState());
  }

  destroy() {
    super.destroy();
    this.unSubs.forEach((u) => u());
    this.unSubs.length = 0;
  }
}

