import { ISpiderUserLowLevelInput, ISpiderCard, ISpiderStack, ISpiderStackMap } from "./types";
import { EmitterOnly } from "../../index";
import { DragDrop } from "../../drag-drop";

interface IAddInputProps {
  cardViews: ISpiderCard[];
  stackMap: ISpiderStackMap;
  userInputEvents: EmitterOnly<ISpiderUserLowLevelInput>;

  isDraggable(clickedCard: ISpiderCard): boolean;
  isDroppable(card: ISpiderCard, dropZone: ISpiderStack): boolean;
  getMovableChain(clickedCard: ISpiderCard): ISpiderCard[];
}

export function addSpiderLowLevelUserInput({
  cardViews,
  stackMap,
  isDroppable,
  isDraggable,
  getMovableChain,
  userInputEvents,
}: IAddInputProps) {
  stackMap.stock.cardPlace.setInteractive({ useHandCursor: true });
  stackMap.stock.cardPlace.on(Phaser.Input.Events.GAMEOBJECT_POINTER_UP, () => {
    userInputEvents.emit("onStockClick", { stock: stackMap.stock });
  });

  cardViews.forEach((card) => {
    card.setInteractive({ useHandCursor: true });
  });

  new DragDrop({
    draggables: cardViews,
    dropZones: stackMap.tableaus,
    isDraggable: (draggable) => isDraggable(draggable as ISpiderCard),
    isDroppable: (draggable, dropZone) =>
      isDroppable(draggable as ISpiderCard, dropZone as ISpiderStack),
    getDraggableGroup: (draggable) => getMovableChain(draggable as ISpiderCard),
    onDrop: (args) => {
      const cards = args.draggingObjects as ISpiderCard[];
      const toStack = args.dropZone as ISpiderStack | undefined;
      userInputEvents.emit("onCardDrop", {
        cards,
        toStack,
      });
    },
    onDragObjectPointerUp: (dragObject) => {
      userInputEvents.emit("onCardClick", { card: dragObject as ISpiderCard });
    },
  });
}

