import { IUnifiedShopItem, IUnifiedShopItemWithId, PurchaseId } from "./types";

export const makeShopItemsWithId = (
  record: Partial<Record<PurchaseId, IUnifiedShopItem>>,
): IUnifiedShopItemWithId[] => {
  return Object.keys(record)
    .map((key) => ({
      id: key,
      ...record[key as PurchaseId],
    }))
    .filter((s) => s.priceLabel != null && s.shopPack != null) as IUnifiedShopItemWithId[];
};
