import { Align } from "@kvisaz/phaser-sugar";
import { LootBoxes, LootParticles, LootSideBar } from "../../../../shared";
import { ILootDto, IRewardAdAnimationConfig, SoundKey } from "../../../../../logic";
import { getSceneBounds, sceneTimeout } from "../../../../../common";

interface ILootEffectProps {
  scene: Phaser.Scene;
  lootEffectConfig: IRewardAdAnimationConfig;
  lootBoxesAmount: number;
  onLootBoxClick?: (clickedBounds: Phaser.Geom.Rectangle) => void;
}

export class LootEffect {
  private lootBoxes: LootBoxes;
  private lootSideBar: LootSideBar;
  private lootParticles: LootParticles;

  constructor(private props: ILootEffectProps) {
    this.lootBoxes = this.createLootBoxes();
    this.lootSideBar = this.createSidebar();
    this.lootParticles = this.createLootParticles();

    this.layout();
  }

  /** для размешения где-нибудь **/
  get boxes() {
    return this.lootBoxes;
  }

  show(visible = true) {
    this.lootBoxes.setVisible(visible);
    this.lootSideBar.setVisible(visible);
  }

  startShaking() {
    this.lootBoxes.startShaking();
  }

  openRandomChest(loots: ILootDto[], onComplete?: () => void) {
    const { scene, lootEffectConfig } = this.props;

    scene.sound.play(SoundKey.chestSlam);
    const clickedBounds = this.lootBoxes.openRandomChest() ?? getSceneBounds(scene);

    const delay = lootEffectConfig.lifeTimeBetweenLastParticleAndClose;

    this.lootParticles?.emit({
      loots,
      clickedBounds,
      onComplete: () => {
        sceneTimeout({
          scene,
          delay,
          callback: () => {
            onComplete?.();
          },
        });
      },
    });
  }

  destroy() {
    this.lootSideBar.destroy();
    this.lootParticles.destroy();
    this.lootBoxes.destroy();
  }

  private createLootBoxes() {
    const { scene, lootEffectConfig, lootBoxesAmount, onLootBoxClick } = this.props;
    return new LootBoxes({
      scene,
      amount: lootBoxesAmount,
      animationConfig: {
        shakingDuration: lootEffectConfig.lootBoxShakingDuration,
      },
      onLootBoxClick,
    });
  }

  private layout() {
    const { lootBoxes, lootSideBar } = this;
    const { scene } = this.props;
    const align = new Align();
    align.anchorSceneScreen(scene).leftIn(lootSideBar, 33).bottomIn(lootSideBar, -86);

    align.anchorSceneScreen(scene).center(lootBoxes);
  }

  private createSidebar() {
    const { scene } = this.props;
    const lootSideBar = new LootSideBar({ scene });
    lootSideBar.setVisible(true);
    return lootSideBar;
  }

  private createLootParticles() {
    const { lootEffectConfig, scene } = this.props;
    return new LootParticles({
      scene,
      animationConfig: {
        explodeDuration: lootEffectConfig.lootBoxExplodeDuration,
        flyDurationMin: lootEffectConfig.lootFlyDuration,
        flyDurationMax: lootEffectConfig.lootFlyDuration,
        flyDelay: lootEffectConfig.lootFlyDelay,
      },
      onLootItemCollectStart: () => {},
      onLootItemCollected: (lootDto) => {
        scene.sound.play(SoundKey.coinFlip);
        this.lootSideBar?.collect(lootDto);
      },
    });
  }
}
