import { ConsumableType } from "./types";

export function multiplyConsumablePack<T extends Partial<Record<ConsumableType, number>>>(pack: T, multiplier: number): T {
  const copy =  {...pack };
  Object.keys(copy).forEach(key => {
    const k = key as ConsumableType;
    const basicValue = copy[k];
    if(basicValue==null) return;
    copy[k] = Math.floor(multiplier * basicValue);
  })
  return copy;
}
