import {AlignObject, layoutColumn, layoutRow} from "@kvisaz/phaser-sugar";
import {ArrayAlignObject} from '@kvisaz/phaser-sugar/dist/layout/ArrayAlignObject/ArrayAlignObject';

export interface ILayoutSpiderProps {
    stock: AlignObject;
    foundations: AlignObject[];
    tableaus: AlignObject[];
}

/** Функция леайута возвращает объект, который можно дальше передвигать и выравнивать **/
export type SpiderLayoutFunc = (props: ILayoutSpiderProps) => ArrayAlignObject;

const cardGap = 12;
const topToTableauGap = 28;

export function basicLayoutSpider({stock, foundations, tableaus}: ILayoutSpiderProps): ArrayAlignObject {
    const topRow = layoutRow({
        children: [stock, ...foundations],
        nextOffsetX: cardGap,
    });

    const tableausRow = layoutRow({
        children: [...tableaus],
        nextOffsetX: cardGap,
    });

    return layoutColumn({
        children: [topRow, tableausRow],
        nextOffsetY: topToTableauGap
    });
}

