import { createSpiderDeck, defaultSpiderConfig, ISpiderConfig, ISpiderExposedState, State, TypedEventsEmitter } from "../../../common";
import { ISpiderGameLogicCommandEvents, ISpiderGameViewEvents } from "./types";

interface IProps {
  spiderConfig?: ISpiderConfig;
}

const defaultState: ISpiderExposedState = {
  step: "idle",
  historyLength: 0,
  dealsLeft: 0,
  isDealPossible: false,
  isUndoPossible: false,
  completedSequences: 0,
  isCollectPossible: false,
  isWin: false,
};

export class SpiderGameSceneViewLogic {
  private readonly state: State<ISpiderExposedState>;
  private readonly unSubs: Array<() => void> = [];

  public readonly spiderSceneLogicCommands: TypedEventsEmitter<ISpiderGameLogicCommandEvents>;
  public readonly spiderSceneViewEvents: TypedEventsEmitter<ISpiderGameViewEvents>;

  private readonly spiderConfig: ISpiderConfig;

  constructor(private readonly props: IProps = {}) {
    this.spiderConfig = props.spiderConfig ?? defaultSpiderConfig;

    this.state = new State<ISpiderExposedState>({ ...defaultState });
    this.unSubs.push(() => this.state.unSubScribeAll());

    this.spiderSceneLogicCommands = new TypedEventsEmitter<ISpiderGameLogicCommandEvents>();
    this.spiderSceneViewEvents = new TypedEventsEmitter<ISpiderGameViewEvents>();
    this.unSubs.push(() => {
      this.spiderSceneLogicCommands.unSubscribeAll();
      this.spiderSceneViewEvents.unSubscribeAll();
    });

    this.subscribeToUiEvents();
    this.subscribeToSpiderEvents();
  }

  destroy() {
    this.unSubs.forEach((u) => u());
    this.unSubs.length = 0;
  }

  observable() {
    return this.state;
  }

  startNewGame({ shuffleDeck }: { shuffleDeck: boolean }) {
    this.state.setState({ ...defaultState });
    const cards = createSpiderDeck({ suitsMode: this.spiderConfig.suitsMode, shuffle: shuffleDeck });
    this.spiderSceneLogicCommands.emit("startSpider", { cards, config: this.spiderConfig });
  }

  private subscribeToUiEvents() {
    const { spiderSceneViewEvents, spiderSceneLogicCommands } = this;

    spiderSceneViewEvents.on("uiNewGameClick", () => {
      this.startNewGame({ shuffleDeck: true });
    });

    spiderSceneViewEvents.on("uiUndoClick", () => {
      if (this.state.getState().isUndoPossible) {
        spiderSceneLogicCommands.emit("undoSpider");
      }
    });

    spiderSceneViewEvents.on("uiHintClick", () => {
      spiderSceneLogicCommands.emit("hintSpider");
    });

    spiderSceneViewEvents.on("uiDealClick", () => {
      if (this.state.getState().isDealPossible) {
        spiderSceneLogicCommands.emit("dealSpider");
      }
    });

    spiderSceneViewEvents.on("uiCollectClick", () => {
      if (this.state.getState().isCollectPossible) {
        spiderSceneLogicCommands.emit("collectSpider");
      }
    });
  }

  private subscribeToSpiderEvents() {
    const { spiderSceneViewEvents } = this;

    spiderSceneViewEvents.on("spiderStateUpdate", (state) => {
      this.state.setState(state);
    });
  }
}

