import { ViewElementBuilder } from "../../../../assets";
import { Anima, finishAnimation, Observable, TypedEventsEmitter } from "../../../../common";
import { ISpiderGameViewEvents } from "../../logic";
import { ISpiderExposedState } from "../../../../common/games/spider";

interface IProps {
  scene: Phaser.Scene;
  gameState: Observable<ISpiderExposedState>;
  spiderSceneViewEvents: TypedEventsEmitter<ISpiderGameViewEvents>;
}

export class SpiderCollectButton extends Phaser.GameObjects.Container {
  private readonly unSubs: Array<() => void> = [];
  private readonly button: Phaser.GameObjects.Container;

  constructor(private readonly props: IProps) {
    super(props.scene);
    const { scene, gameState, spiderSceneViewEvents } = props;
    const builder = new ViewElementBuilder(scene);

    this.button = builder.buttonAutoComplete(() => {
      spiderSceneViewEvents.emit("uiCollectClick");
      this.clearAnimate();
      this.button.setVisible(false);
    });
    this.add(this.button);
    scene.add.existing(this);

    const applyState = (state: ISpiderExposedState) => {
      this.button.setVisible(state.isCollectPossible === true);
      if (state.isCollectPossible) {
        this.callToActionAnimate();
      } else {
        this.clearAnimate();
      }
    };

    this.callToActionAnimate();

    this.unSubs.push(gameState.on(applyState, "isCollectPossible"));
    applyState(gameState.getState());
  }

  destroy() {
    super.destroy();
    this.unSubs.forEach((unSub) => unSub());
    this.unSubs.length = 0;
  }

  private callToActionAnimate() {
    const singleDuration = 900;
    const pressAmount = 22;
    Anima.popItem({
      target: this.button,
      repeat: pressAmount,
      duration: pressAmount * singleDuration,
      scaleAmount: 1,
      upDistance: 25,
    });
    this.button.postFX?.addGlow();
  }

  private clearAnimate() {
    finishAnimation(this.button);
    this.button.postFX?.clear();
  }
}

